  ],
  "data_model": [
    {
      "name": "ShortLink",
      "fields": [
        "int Id (Primary Key, Autoincrement)",
        "string Code (Unique Index, MaxLength 64, Required)",
        "string OriginalUrl (Required, Unlimited Length)",
        "DateTime CreatedAt (UTC, Required)",
        "DateTime? ExpiresAt (UTC, Nullable)",
        "long ClickCount (Default 0, Required)",
        "DateTime? LastVisitedAt (UTC, Nullable)"
      ]
    }
  ],
  "decisions": [
    {
      "id": "D1",
      "title": "Use HTTP 307 Temporary Redirect for link resolution",
      "choice": "Return HTTP 307 Temporary Redirect with the target URL in the Location header.",
      "rationale": "HTTP 301 is aggressively and permanently cached by user agents, which prevents subsequent clicks from contacting the server and skews analytics tracking. HTTP 307 guarantees every visit reaches the service while maintaining the HTTP method.",
      "alternatives": [
        "HTTP 301 Moved Permanently (cached by browsers, breaks click tracking)",
        "HTTP 302 Found (may inadvertently alter HTTP POST methods to GET in older clients)"
      ]
    },
    {
      "id": "D2",
      "title": "Synchronous DNS resolution for pre-shorten SSRF mitigation",
      "choice": "Perform IP address parsing and DNS lookup using Dns.GetHostAddressesAsync during POST /shorten to block loopback, link-local, private IPv4 (RFC 1918), and private IPv6 ranges.",
      "rationale": "Protects internal infrastructure, cloud metadata endpoints (e.g., 169.254.169.254), and local developer services from server-side request forgery before persisting any link.",
      "alternatives": [
        "Regex/Prefix matching on host strings only (fails when public domain names resolve to private IP addresses)",
        "Validating on redirect execution (too late, creates open redirect / SSRF vector at execution time)"
      ]
    },
    {
      "id": "D3",
      "title": "ASP.NET Core Built-in Partitioned Rate Limiter for abuse mitigation",
      "choice": "Use ASP.NET Core RateLimiter middleware configured with a FixedWindowRateLimiter partitioned by RemoteIpAddress.",
      "rationale": "Built directly into .NET without external dependencies or Redis requirements, natively outputs 429 Too Many Requests and Retry-After headers, and fulfills R8 cleanly.",
      "alternatives": [
        "Third-party AspNetCoreRateLimit package (external dependency, unnecessary complexity on .NET 10)",
        "Custom middleware with ConcurrentDictionary (reinventing built-in framework features)"
      ]
    },
    {
      "id": "D4",
      "title": "Retain expired link metadata for analytics access while disabling redirection",
      "choice": "Keep expired ShortLink records in the SQLite database; return 404 on GET /{code} when DateTime.UtcNow > ExpiresAt, but permit GET /analytics/{code} to return historical visit metrics.",
      "rationale": "Prevents alias hijacking, preserves historical analytics reporting, and complies with acceptance criteria requiring GET /{code} to return 404 after expiration without dropping data.",
      "alternatives": [
        "Hard-delete expired records on expiration check (erases all analytics and allows immediate alias hijacking)",
        "Return 410 Gone for GET /{code} (acceptance criteria R4 specifically requires HTTP 404 Not Found)"
      ]
    }
  ],
